({String title, String message}) _quoteMismatchText({
  required bool sameRecipient,
  required bool sameAmount,
}) {
  final changed = switch ((sameRecipient, sameAmount)) {
    (false, false) => "recipient and amount",
    (false, true) => "recipient",
    _ => "amount",
  };
  return (
    title: "${changed.capitalize()} changed",
    message:
        "The payment request asked for a different $changed. "
        "The seller may not recognize this payment.",
  );
}

/// Map a wallet [CryptoCurrency] (plus optional token symbol) to the
/// library's [CryptoCoin] descriptor.
CryptoCoin cryptoCoinFor(CryptoCurrency currency, {String? tokenSymbol}) =>
    CryptoCoin(
      ticker: tokenSymbol ?? currency.ticker,
      prettyName: currency.prettyName,
      displayName: tokenSymbol ?? currency.prettyName,
    );

typedef BusinessDetail = ({String label, String value, Uri? uri});

const _tokenMismatchTitle = "Different token";
const _tokenMismatchMessage =
    "The payment request is for a token with a different contract address "
    "than this wallet's token. Scan the code from the wallet holding that "
    "token.";

class OpenCryptoPaySendHandler {
  OpenCryptoPaySendHandler({
    required this.coin,
    required this.sendToController,
    required this.onAmountReceived,
    required this.setValidAddress,
    this.tokenSymbol,
    this.tokenDecimals,
    this.tokenContractAddress,
    @visibleForTesting OpenCryptoPayController? controller,
  }) : _controller =
           controller ??
           OpenCryptoPayController(
             service: OpenCryptoPayService(
               client: StackClient(proxyInfo: _proxyInfo),
             ),
           );

  static ({InternetAddress host, int port})? _proxyInfo() {
    if (AppConfig.hasFeature(AppFeature.tor) && Prefs.instance.useTor) {
      return TorService.sharedInstance.getProxyInfo();
    } else {
      return null;
    }
  }

  final CryptoCurrency coin;
  final TextEditingController sendToController;
  final void Function(Amount amount) onAmountReceived;
  final void Function(String address) setValidAddress;

  /// Set for token wallets so the request targets the token and amounts use
  /// its decimals.
  final String? tokenSymbol;
  final int? tokenDecimals;

  /// Set for token wallets; a request for another contract is refused.
  final String? tokenContractAddress;

  int get _fractionDigits => tokenDecimals ?? coin.fractionDigits;

  final OpenCryptoPayController _controller;
  OpenCryptoPaySession? _session;
  Amount? _quotedAmount;
  bool _quoteOverridden = false;

  /// Whether a proof submission got no answer, so the provider may hold it.
  bool _deliveryUnconfirmed = false;
  bool _feeCheckInFlight = false;

  /// Whether the user chose to send despite a recipient or amount that
  /// differs from the payment request.
  bool get quoteOverridden => _quoteOverridden;

  void reset() {
    _session = null;
    _quotedAmount = null;
    _quoteOverridden = false;
    _deliveryUnconfirmed = false;
  }

  Future<void> showQuoteExpiredError(
    BuildContext context, {
    bool paymentNotSent = false,
  }) => _showError(
    context: context,
    title: OpenCryptoPayStrings.quoteExpiredTitle,
    message: OpenCryptoPayStrings.quoteExpiredMessage(
      paymentNotSent: paymentNotSent,
    ),
  );

  bool get requiresBroadcast => _session?.requiresBroadcast ?? true;

  bool get isQuoteExpired => _session?.isQuoteExpired ?? false;

  List<BusinessDetail> get businessDetails {
    final details = _session?.details;
    if (details == null) return const [];
    final recipient = details.recipient;
    BusinessDetail? detail(String label, String? value, {Uri? uri}) =>
        value == null || value.isEmpty
        ? null
        : (label: label, value: value, uri: uri);
    final legalName = details.legalName;
    return [
      legalName == null
          ? detail("Name", details.displayName)
          : detail("Legal name", legalName),
      if (recipient != null) ...[
        detail("Postal address", recipient.postalAddress),
        detail("Phone number", recipient.phone, uri: recipient.phoneUri),
        detail("Email", recipient.mail, uri: recipient.mailUri),
        detail("Website", recipient.website, uri: recipient.websiteUri),
        detail("Registration number", recipient.registrationNumber),
      ],
    ].nonNulls.toList();
  }

  bool isActivePaymentFor(String? recipientAddress) =>
      _session?.isActivePaymentFor(recipientAddress) ?? false;

  /// Whether sending [amount] to [address] may proceed. A pending payment
  /// request with another recipient or amount asks for confirmation.
  Future<bool> confirmSend(
    BuildContext context,
    String? address,
    Amount amount,
  ) async {
    final session = _session;
    if (session == null || session.isCompleted || session.isQuoteExpired) {
      return true;
    }
    final sameRecipient = session.isActivePaymentFor(address);
    final sameAmount = _quotedAmount == null || amount == _quotedAmount;
    if (sameRecipient && sameAmount) return true;
    if (!context.mounted) return false;
    final text = _quoteMismatchText(
      sameRecipient: sameRecipient,
      sameAmount: sameAmount,
    );
    final proceed = await _confirm(context, text.title, text.message);
    if (proceed) _quoteOverridden = true;
    return proceed;
  }

  /// The fee to build the transaction with: the given one, raised to the
  /// payment request's minimum when below it. Null when the send must stop.
  /// [feeRateApplies] is false when the send builds its own fee.
  Future<OpenCryptoPaySendFee?> sendFee(
    BuildContext context,
    Wallet wallet, {
    required String? address,
    required Amount amount,
    required FeeRateType feeRateType,
    int? satsPerVByte,
    EthEIP1559Fee? ethFee,
    bool feeRateApplies = true,
  }) async {
    final chosen = (
      feeRateType: feeRateType,
      satsPerVByte: satsPerVByte,
      ethFee: ethFee,
    );
    final session = _minFeeSessionFor(address);
    if (!feeRateApplies || session == null) return chosen;
    // A second Preview tap during the check is ignored.
    if (_feeCheckInFlight) return null;
    _feeCheckInFlight = true;
    try {
      return await openCryptoPaySendFee(
        context,
        wallet,
        amount: amount,
        minFee: session.minFee,
        chosen: chosen,
        confirm: _confirm,
        unmet: _notify,
      );
    } finally {
      _feeCheckInFlight = false;
    }
  }

  /// Whether a prepared transaction's fee reaches the payment request's
  /// minimum, for sends that build their own fee.
  Future<bool> preparedFeeMeetsMinimum(
    BuildContext context,
    Wallet wallet, {
    required String? address,
    required Amount? fee,
  }) async {
    final session = _minFeeSessionFor(address);
    if (session == null) return true;
    return openCryptoPayPreparedFeeMeetsMinimum(
      context,
      wallet,
      minFee: session.minFee,
      fee: fee,
      unmet: _notify,
    );
  }

  /// The active payment session for [address] when it carries a minimum fee.
  OpenCryptoPaySession? _minFeeSessionFor(String? address) {
    final session = _session;
    if (session == null ||
        session.minFee <= 0 ||
        !session.isActivePaymentFor(address)) {
      return null;
    }
    return session;
  }

  Future<void> _notify(BuildContext context, String title, String message) =>
      _showError(context: context, title: title, message: message);

  Future<bool> _confirm(
    BuildContext context,
    String title,
    String message, {
    String confirmLabel = "Continue",
  }) async {
    final proceed = await showDialog<bool>(
      context: context,
      barrierDismissible: false,
      builder: (context) => BasicDialog(
        title: title,
        message: message,
        leftButton: SecondaryButton(
          label: "Cancel",
          onPressed: () => Navigator.of(context).pop(false),
        ),
        rightButton: PrimaryButton(
          label: confirmLabel,
          onPressed: () => Navigator.of(context).pop(true),
        ),
        flex: true,
      ),
    );
    return proceed ?? false;
  }

  Future<void> _showError({
    required BuildContext context,
    required String title,
    required String message,
  }) async {
    if (!context.mounted) return;
    await showDialog<void>(
      context: context,
      builder: (_) => StackOkDialog(
        title: title,
        message: message,
        desktopPopRootNavigator: Util.isDesktop,
        maxWidth: Util.isDesktop ? 600 : null,
      ),
    );
  }

  Future<void> handle(BuildContext context, String qrData) async {
    final result = await showLoading<OpenCryptoPayResult>(
      whileFuture: _controller.run(
        qrData: qrData,
        coin: cryptoCoinFor(coin, tokenSymbol: tokenSymbol),
        onError: (e, s) => Logging.instance.w(
          "OpenCryptoPay flow failed",
          error: e,
          stackTrace: s,
        ),
      ),
      context: context,
      rootNavigator: Util.isDesktop,
      message: OpenCryptoPayStrings.loading,
    );

    if (!context.mounted) return;

    switch (result) {
      case null:
        await _showError(
          context: context,
          title: OpenCryptoPayStrings.genericErrorTitle,
          message: OpenCryptoPayStrings.genericErrorMessage,
        );
      case OpenCryptoPayFailure():
        final text = OpenCryptoPayStrings.failure(result);
        await _showError(
          context: context,
          title: text.title,
          message: text.message,
        );
      case OpenCryptoPaySuccess() when result.session.isQuoteExpired:
        await showQuoteExpiredError(context);
      case OpenCryptoPaySuccess() when _isOtherToken(result):
        await _showError(
          context: context,
          title: _tokenMismatchTitle,
          message: _tokenMismatchMessage,
        );
      case OpenCryptoPaySuccess():
        _applySuccess(result);
    }
  }

  bool _isOtherToken(OpenCryptoPaySuccess result) {
    final requested = result.tokenContractAddress;
    final held = tokenContractAddress;
    return requested != null &&
        held != null &&
        requested.toLowerCase() != held.toLowerCase();
  }

  void _applySuccess(OpenCryptoPaySuccess result) {
    _session = result.session;
    _deliveryUnconfirmed = false;

    // Prefill the form in place.
    final address = result.address;
    sendToController.text = address;

    final rawAmount = result.amountInSmallestUnit(_fractionDigits);
    final quoted = rawAmount == null
        ? null
        : Amount(rawValue: rawAmount, fractionDigits: _fractionDigits);
    _quotedAmount = quoted;
    _quoteOverridden = false;
    if (quoted != null) onAmountReceived(quoted);

    setValidAddress(address);
  }

  Future<bool> submitProof(BuildContext context, String txProof) async {
    final session = _session;
    if (session == null) return true;

    final result = await session.submitProof(txProof);
    switch (result) {
      case OpenCryptoPayProofAccepted():
        _session = null;
        return true;
      case OpenCryptoPayProofQuoteExpired(:final error):
        Logging.instance.w(
          "OpenCryptoPay proof submission failed",
          error: error,
        );
        if (!context.mounted) return false;
        await showQuoteExpiredError(context, paymentNotSent: true);
        return false;
      case OpenCryptoPayProofFailed(:final error, :final providerAnswered):
        Logging.instance.w(
          "OpenCryptoPay proof submission failed",
          error: error,
        );
        if (!context.mounted) return false;
        _deliveryUnconfirmed |= !providerAnswered;
        final text = OpenCryptoPayStrings.proofFailure(
          requiresBroadcast: session.requiresBroadcast,
          providerAnswered: providerAnswered && !_deliveryUnconfirmed,
        );
        final retry = await _confirm(
          context,
          text.title,
          text.message,
          confirmLabel: "Retry",
        );
        if (!retry || !context.mounted) return false;
        return submitProof(context, txProof);
    }
  }
}
